// Builds dist/:
//   zhaoui.css / .js (+ .min)     everything in one file each: the "one CSS, one JS" build
//   zhaoui-icons.js               optional: the full icon set
//   zhaoui-style-glass.css        optional: glass style pack
//   modular/                      the same code split so a page only loads what it uses:
//       core.css / core.js            tokens, base, ~20 light components, auto-init (required)
//       select.css / select.js        select + cascader
//       date.css / date.js            date, date range, time, date-time pickers
//       brand.js                      token runtime: ZhaoUI.setBrand() / logo colour extraction
// Every JS/CSS file also ships a minified copy; JS minified files have a source map.
import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync, copyFileSync, rmSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gzipSync } from 'fflate';   // not node:zlib: its output changes between Node versions, and these sizes end up in the README inside the release zip
import esbuild from 'esbuild';
import { extractComponents, withUsedKeyframes } from './css.mjs';
import { readBase } from '../../../demo/base.mjs';
import { buildDocs } from './docs.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const pkg = resolve(here, '..'), root = resolve(pkg, '..', '..');
const demo = join(root, 'demo'), tokens = join(root, 'packages', 'tokens', 'dist'), dist = join(pkg, 'dist'), mod = join(dist, 'modular');
const read = (p) => readFileSync(p, 'utf8');
rmSync(dist, { recursive: true, force: true }); mkdirSync(mod, { recursive: true });
const TARGET = ['chrome111', 'safari16.4', 'firefox113'];      // same floor as the tokens package's browserslist

// [fragment, selectors to leave out]. Leave-outs are classes that belong to the demo page's own examples, not to the library.
const CSS_FRAGMENTS = [
  ['00-core'], ['20-popover'], ['30-dropdown', /\.zh-dd-/], ['30-dropdown-menu', /\.zh-(sel|cas)-|\.zh-btn\b|\.zh-dd-(chip|chips|ctx|place|split)/, '30-dropdown'], ['33-input'],
  ['31-datepicker', /\.zh-dp-(inline|events|detail|legend|chip)/],
  ['32-slider-rating', /\.zh-rate-(sum|score|dist)/],
  ['40-badge', /\.zh-bdg-(lab|menu)|\.zh-avatar-list/],
  ['41-panel'],
  ['43-timeline', /\.zh-wiz/],
  ['34-upload', /\.zh-upload-(avatar|card|dir|add|file|sr)/],
  ['50-navigation-cmd', null, '50-navigation', /\.zh-cmd/],
  ['44-tree', /\.zh-(tselect|tree-(log|ghost|dragging|act|actions|edit|retry|empty))/],
  ['50-navigation', /\.zh-(bc|anchor|tabs?|tabpanel|cmd)\b|\.zh-cmd-|\.zh-nav-(frame|ghost)|\.zh-side-(demo|main|here)|\.zh-backtop-ring/],
  ['42-progress', /\.zh-(upq|pgd|cd)-?/],
  ['51-pagination', /\.zh-pgx/],
];
// The heavy, self-contained parts that modular builds split out. Everything else is "core".
const GROUPS = {
  select: { title: '下拉选择与级联选择', components: ['select', 'cascader'], fragments: ['30-dropdown'], icons: ['search-x'] },
  upload: { title: '文件上传', components: ['upload'], fragments: ['34-upload'], icons: ['cloud-upload'] },
  tree:   { title: '树', components: ['tree'], fragments: ['44-tree'], icons: [] },
  chart:  { title: '基础图表', components: ['chart'], fragments: ['chart'], icons: [] },
  command: { title: '命令面板', components: ['command'], fragments: ['50-navigation-cmd'], icons: [] },
  date:   { title: '日期、日期范围、时间、日期时间选择', components: ['datepicker'], fragments: ['31-datepicker'], icons: ['calendar-days', 'calendar-range', 'calendar-clock', 'clock', 'arrow-right'] },
};
const CORE_ICONS = ['chevron-right', 'chevron-down', 'chevron-up', 'chevron-left', 'x', 'check', 'info', 'circle-check', 'circle-x', 'triangle-alert', 'circle-alert', 'loader-circle', 'search', 'plus', 'minus', 'eye', 'eye-off', 'pencil', 'user', 'chevrons-left', 'chevrons-right', 'star', 'heart', 'layout-dashboard', 'file-text', 'settings', 'panel-left-close', 'panel-left-open', 'menu'];
const ALL_ICONS = [...CORE_ICONS, ...Object.values(GROUPS).flatMap((g) => g.icons)];

const version = JSON.parse(read(join(pkg, 'package.json'))).version;
const banner = (kind) => `/*! ZhaoUI ${version} · ${kind} · generated by packages/ui/scripts/build.mjs, do not edit by hand */`;
const stats = [];                                                            // rows for the size table
const gz = (s) => gzipSync(typeof s === 'string' ? new TextEncoder().encode(s) : s, { level: 9 }).length;
function emit(rel, kind, code, desc, opts = {}) {
  const ext = kind.startsWith('css') ? 'css' : 'js', base = rel.replace(/\.(css|js)$/, ''), b = banner(kind);
  writeFileSync(join(dist, rel), b + '\n' + code);
  const min = esbuild.transformSync(code, { loader: ext, minify: true, target: TARGET, legalComments: 'none', banner: b, ...(ext === 'js' ? { sourcemap: true, sourcefile: rel } : {}) });
  writeFileSync(join(dist, `${base}.min.${ext}`), min.code + (ext === 'js' ? `\n//# sourceMappingURL=${base.split('/').pop()}.min.js.map\n` : ''));
  if (ext === 'js') writeFileSync(join(dist, `${base}.min.js.map`), min.map);
  stats.push({ name: rel, desc, raw: (b.length + 1 + code.length), min: min.code.length, gzip: gz(min.code), group: opts.group || 'main' });
}

// ---------- CSS ----------
const dropped = [];
const baseHtml = readBase();   // demo/base.html with the pieces in demo/base/ put back
const baseStyle = baseHtml.match(/<style>([\s\S]*?)<\/style>/)[1];
const cssParts = [{ name: 'base.html', css: withUsedKeyframes(extractComponents(baseStyle, dropped, null)) }]
  .concat(CSS_FRAGMENTS.map(([f, ex, srcDir, only]) => ({ name: f, css: withUsedKeyframes(extractComponents(read(join(demo, 'fragments', srcDir || f, 'style.css')), dropped, ex || null, only || null)) }))
  .concat([{ name: 'chart', css: read(join(pkg, 'src', 'chart.css')) }]));
const block = (ps) => ps.map((p) => `/* ---- ${p.name} ---- */\n${p.css}`).join('\n\n');
const head = read(join(tokens, 'zhaoui.css')) + '\n\n/* ==== base ==== */\n' + read(join(pkg, 'src', 'base.css')) + '\n' + read(join(pkg, 'src', 'more.css')) + '\n\n/* ==== components ==== */\n';
const inGroup = (name) => Object.values(GROUPS).some((g) => g.fragments.includes(name));
emit('zhaoui.css', 'css', head + block(cssParts) + '\n', 'Token 变量 + 全部组件样式');
emit('modular/core.css', 'css core', head + block(cssParts.filter((p) => !inGroup(p.name))) + '\n', '核心：Token、基础、通用组件样式', { group: 'modular' });
for (const [g, def] of Object.entries(GROUPS)) emit(`modular/${g}.css`, `css ${g}`, block(cssParts.filter((p) => def.fragments.includes(p.name))) + '\n', `${def.title}的样式`, { group: 'modular' });
// The demo page can simulate a screen size with <html data-screen="phone|tablet|...">; the responsive utilities carry selectors for that.
// The library only follows the real viewport, so keep the media-query half and drop the simulation half.
const unscreen = (css) => css.replace(/:where\(html:not\(\[data-screen\]\), html\[data-screen="auto"\]\) /g, '').replace(/^:where\(html\[data-screen[^\n]*\n/gm, '');
// Optional utility classes (spacing, flex/grid, text, responsive hide/show, animation).  Kept out of zhaoui.css so pages that don't use them don't pay for them.
const utilParts = [['53-utilities', /\.zh-(ut|util)-|\.zh-input\b/], ['52-motion', /\.zh-mo-|\.zh-btn\b/]]
  .map(([f, ex]) => ({ name: f, css: withUsedKeyframes(extractComponents(unscreen(read(join(demo, 'fragments', f, 'style.css'))), dropped, ex)) }));
emit('zhaoui-utilities.css', 'css utilities', block(utilParts) + '\n', '可选：公共类（间距、布局、文字、响应式显示隐藏、动画）', { group: 'optional' });
emit('zhaoui-marketing.css', 'css marketing', read(join(pkg, 'src', 'marketing.css')), '可选：营销页区块（页宽、区块、hero、特性卡、价格卡）', { group: 'optional' });
emit('zhaoui-style-glass.css', 'css glass', read(join(tokens, 'zhaoui-style-glass.css')), '可选：玻璃拟态风格包（实验性）', { group: 'optional' });

// ---------- icons (from the sprite embedded in the demo) ----------
const sprite = {};
for (const m of baseHtml.matchAll(/<symbol id="zi-([^"]+)" viewBox="0 0 24 24">([\s\S]*?)<\/symbol>/g)) sprite[m[1]] = m[2];
const missingIcons = ALL_ICONS.filter((n) => !sprite[n]);
if (missingIcons.length) throw new Error('icons missing from sprite: ' + missingIcons.join(', '));
const pick = (names) => Object.fromEntries(names.map((n) => [n, sprite[n]]));
emit('zhaoui-icons.js', 'js icons', `(function(){if(typeof window==='undefined')return;var Z=window.ZhaoUI;if(!Z||!Z.icons){throw new Error('load zhaoui.js (or modular/core.js) before zhaoui-icons.js');}\nvar S=${JSON.stringify(sprite)};\nObject.keys(S).forEach(function(n){Z.icons.add(n,S[n]);});})();\n`, '可选：完整 Lucide 图标集（372 个）', { group: 'optional' });

// ---------- JS ----------
const coreLib = read(join(demo, 'fragments', '00-core', 'script.js')).replace(/^window\.ZHDemo = ZH;\s*$/m, '');
const compDir = join(pkg, 'src', 'components');
const compNames = readdirSync(compDir).sort().filter((d) => existsSync(join(compDir, d, 'behavior.js')));
const beh = (d) => `/* ---- component: ${d} ---- */\n(function () {\n${read(join(compDir, d, 'behavior.js'))}\n})();`;
const grouped = new Set(Object.values(GROUPS).flatMap((g) => g.components));
for (const c of grouped) if (!compNames.includes(c)) throw new Error('GROUPS names a component with no behavior.js: ' + c);
const iconsJs = (names) => read(join(pkg, 'src', 'icons.js')).replace(/\/\*@ICONS\*\/[\s\S]*?\/\*@END\*\//, JSON.stringify(pick(names)));
const runtime = read(join(tokens, 'zhaoui.runtime.js'));
const coreBody = (names, icons) => `/* ---- core ---- */\n(function () {\n${coreLib}\n})();\n/* ---- icons ---- */\n(function () {\n${iconsJs(icons)}\n})();\n/* ---- registry ---- */\n(function () {\n${read(join(pkg, 'src', 'registry.js'))}\n})();\n${names.map(beh).join('\n')}\n/* ---- boot ---- */\n(function () {\n${read(join(pkg, 'src', 'boot.js'))}\n})();\n`;
const CLOSE = "})(typeof window !== 'undefined' ? window : undefined);\n";   // importing the package on a server (SSR) must not throw
const open = (extra = '') => `\n(function (global) {\n'use strict';\nif (!global || typeof document === 'undefined') return;\nvar ZhaoUI = global.ZhaoUI = global.ZhaoUI || {}, ZH = ZhaoUI.ZH || {};\n${extra}`;
// the brand runtime assigns window.ZhaoUI itself; fold it into an existing ZhaoUI instead of replacing it, whichever file loaded first
const brandJs = `(function () {\nvar prev = typeof window !== 'undefined' ? window.ZhaoUI : undefined;\n${runtime}\nif (typeof window !== 'undefined' && prev && window.ZhaoUI !== prev) { var fresh = window.ZhaoUI; Object.keys(fresh).forEach(function (k) { if (!(k in prev)) prev[k] = fresh[k]; }); window.ZhaoUI = prev; }\n})();\n`;
const guard = "if (!ZhaoUI.ZH) throw new Error('ZhaoUI: load modular/core.js (or zhaoui.js) before this file');\n";

const allNames = compNames;
emit('zhaoui.js', 'js', runtime + open(`ZhaoUI.version = ${JSON.stringify(version)};\n`) + coreBody(allNames, ALL_ICONS) + CLOSE, '主题运行时 + 全部组件行为 + 内置图标 + 自动初始化');
emit('modular/brand.js', 'js brand', brandJs, '品牌色运行时：ZhaoUI.setBrand()、Logo 取色（可选）', { group: 'modular' });
emit('modular/core.js', 'js core', open(`ZhaoUI.version = ${JSON.stringify(version)};\n`) + coreBody(compNames.filter((c) => !grouped.has(c)), CORE_ICONS) + CLOSE, '核心：组件注册与自动初始化 + 通用组件行为（必须最先加载）', { group: 'modular' });
for (const [g, def] of Object.entries(GROUPS)) {
  const icons = `/* ---- icons ---- */\n(function () { var I = ${JSON.stringify(pick(def.icons))}; Object.keys(I).forEach(function (n) { ZhaoUI.icons.add(n, I[n]); }); })();\n`;
  emit(`modular/${g}.js`, `js ${g}`, open() + guard + 'ZH = ZhaoUI.ZH;\n' + icons + def.components.map(beh).join('\n') + '\n' + CLOSE, `${def.title}的行为（在 core.js 之后加载）`, { group: 'modular' });
}

// ---------- report + docs ----------
const kb = (n) => (n / 1024).toFixed(1) + ' KB';
const fileRows = stats.map((s) => ({ name: s.name, desc: s.desc, size: `${kb(s.raw)} → ${kb(s.min)}，gzip ${kb(s.gzip)}` }));
const docsResult = buildDocs({ pkg, root, version, coreIcons: ALL_ICONS, files: fileRows, stats });
console.log(`docs: ${docsResult.components.length} components -> packages/ui/docs, skills/zhaoui (SKILL.md + references)`);
console.log(`built @zhaoui/ui ${version}`);
for (const s of stats) console.log('  ' + s.name.padEnd(24) + kb(s.raw).padStart(10) + ' → ' + kb(s.min).padStart(9) + '   gzip ' + kb(s.gzip).padStart(8));
const uniq = [...new Set(dropped)];
console.log(`css: ${uniq.length} zh- rules skipped (demo-only selectors)` + (process.env.VERBOSE ? ':\n  ' + uniq.join('\n  ') : ' (VERBOSE=1 to list)'));
